<?php
require_once __DIR__.'/../config/app.php';require_auth();if(!can_access_menu_item('marketing_report_vendors')){header('Location: '.app_url('marketing.php?view=reports'));exit;}ensure_destination_visit_schema();ensure_vendor_type_schema();
$search=trim((string)($_GET['q']??''));$status=in_array((string)($_GET['status']??''),['active','inactive'],true)?(string)$_GET['status']:'';$conditions=['1=1'];$params=[];
if($search!==''){$like='%'.$search.'%';$conditions[]='(v.vendor_name LIKE ? OR v.contact_name LIKE ? OR v.email LIKE ? OR v.phone LIKE ? OR v.area LIKE ? OR l.town_name LIKE ? OR l.mmda_name LIKE ? OR l.region_name LIKE ?)';array_push($params,$like,$like,$like,$like,$like,$like,$like,$like);}if($status!==''){$conditions[]='v.is_active=?';$params[]=$status==='active'?1:0;}
$sql="SELECT v.*,l.region_name,l.mmda_name AS district_name,l.town_name,creator.full_name AS added_by FROM vendors v LEFT JOIN locations l ON l.id=v.location_id LEFT JOIN users creator ON creator.id=v.created_by_user_id WHERE ".implode(' AND ',$conditions)." ORDER BY v.vendor_name,v.id";$statement=db()->prepare($sql);$statement->execute($params);$vendors=$statement->fetchAll();
$pageTitle='Vendors';$breadcrumbs=[['label'=>'Home','url'=>app_url('index.php')],['label'=>'Marketing','url'=>app_url('marketing.php')],['label'=>'Reports','url'=>app_url('marketing.php?view=reports')],['label'=>'Vendors']];$internalBackUrl=app_url('marketing.php?view=reports');require_once __DIR__.'/../includes/header.php';
?>
<section class="management-panel management-panel--table"><div class="management-heading"><div><span class="section-kicker">Marketing Reports</span><h1>Vendors</h1><p>Complete vendor directory and account status.</p></div><div class="management-icon"><i class="fa-solid fa-store"></i></div></div>
<form class="filter-bar marketing-notes-filter" method="get" data-vendor-report-filter><label class="form-field marketing-notes-filter__search"><span><i class="fa-solid fa-magnifying-glass"></i>Search vendors</span><div><i class="fa-solid fa-magnifying-glass"></i><input type="search" name="q" value="<?=e($search)?>" placeholder="Vendor, contact, phone, town or region"></div></label><label class="form-field"><span><i class="fa-solid fa-toggle-on"></i>Status</span><select name="status" data-popup-select data-popup-search><option value="">All statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactive</option></select></label><div class="marketing-notes-filter__actions"><button class="login-button"><i class="fa-solid fa-filter"></i><span>Show Vendors</span></button><a class="secondary-button" href="<?=e(app_url('marketing-vendors-report.php'))?>" data-vendor-report-clear><i class="fa-solid fa-rotate-left"></i><span>Clear</span></a></div></form>
<div data-vendor-report-results aria-live="polite"><div class="marketing-notes-result-bar"><span><i class="fa-solid fa-store"></i></span><p><strong><?=number_format(count($vendors))?></strong> vendor<?=count($vendors)===1?'':'s'?> found</p></div><?php if($vendors):?><div class="table-wrap marketing-notes-table-wrap"><table class="data-table marketing-notes-table"><thead><tr><th>Vendor</th><th>Type</th><th>Contact</th><th>Location</th><th>Status</th><th>Date Added</th><th>Action</th></tr></thead><tbody><?php foreach($vendors as $vendor):?><tr><td data-label="Vendor"><div class="marketing-note-entity"><span class="table-avatar"><?php if($vendor['profile_image']):?><img src="<?=e(app_url((string)$vendor['profile_image']))?>" alt=""><?php else:?><i class="fa-solid fa-store"></i><?php endif;?></span><span><strong><?=e((string)$vendor['vendor_name'])?></strong><small><?=e((string)$vendor['email'])?></small></span></div></td><td data-label="Type"><span class="status-badge <?=($vendor['vendor_type']??'regular')==='sor'?'is-warning':'is-active'?>"><?=($vendor['vendor_type']??'regular')==='sor'?'SoR':'Regular'?></span></td><td data-label="Contact"><strong><?=e((string)($vendor['contact_name']?:'Not provided'))?></strong><span class="muted-text"><?=e((string)($vendor['phone']?:'No phone'))?></span></td><td data-label="Location"><strong><?=e((string)($vendor['town_name']?:'Not assigned'))?></strong><span class="muted-text"><?=e(implode(' · ',array_filter([(string)$vendor['district_name'],(string)$vendor['region_name'],(string)$vendor['area']])))?></span></td><td data-label="Status"><span class="status-badge <?=$vendor['is_active']?'is-active':'is-inactive'?>"><?=$vendor['is_active']?'Active':'Inactive'?></span></td><td data-label="Date Added"><?=e(date('d M Y',strtotime((string)$vendor['created_at'])))?><span class="muted-text"><?=e((string)($vendor['added_by']?:'System'))?></span></td><td data-label="Action"><a class="secondary-button secondary-button--small" href="<?=e(app_url('vendor-setup.php?edit='.(int)$vendor['id'].'&return_to='.rawurlencode(app_url('marketing-vendors-report.php'))))?>"><i class="fa-solid fa-pen"></i><span>Edit</span></a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="marketing-notes-empty"><span><i class="fa-solid fa-store"></i></span><h2>No vendors found</h2><p>No vendors match the selected filters.</p></div><?php endif;?></div></section>
<script>(()=>{const form=document.querySelector('[data-vendor-report-filter]');if(!form)return;const search=form.querySelector('input[type="search"]'),status=form.querySelector('select[name="status"]');let timer,controller;const refresh=async()=>{controller?.abort();controller=new AbortController();const url=new URL(form.action||location.href,location.href);url.search=new URLSearchParams(new FormData(form)).toString();form.classList.add('is-loading');try{const response=await fetch(url,{signal:controller.signal});const doc=new DOMParser().parseFromString(await response.text(),'text/html'),incoming=doc.querySelector('[data-vendor-report-results]'),current=document.querySelector('[data-vendor-report-results]');if(incoming&&current){current.replaceWith(incoming);history.replaceState({},'',url);}}catch(error){if(error.name!=='AbortError')form.requestSubmit();}finally{form.classList.remove('is-loading');}};const queue=delay=>{clearTimeout(timer);timer=setTimeout(refresh,delay)};search?.addEventListener('input',()=>queue(350));status?.addEventListener('change',()=>queue(80));form.querySelector('[data-vendor-report-clear]')?.addEventListener('click',event=>{event.preventDefault();if(search)search.value='';if(status)status.value='';refresh();});form.addEventListener('submit',event=>{event.preventDefault();refresh();});})();</script>
